import{toLatinDigits}from"./validate.js";export function byCode(e,t){return e.find(e=>e.code===t||e.alias_codes?.includes(t))??null}function match(e,t){return t?{bank:t,supported:t.supported,successor:t.status==="merged"?byCode(e,t.merged_into):null}:null}export function detectByBin(e,t){if(!t||t.length<6)return null;const n=t.slice(0,6);return match(e,e.find(e=>e.bins.includes(n)))}export function detectByIbanCode(e,t){return t?match(e,byCode(e,t)):null}export function formerName(e){return e.old_fa??e.fa}export function selectable(e){const t=new Intl.Collator("fa");return e.filter(e=>e.supported).sort((e,n)=>t.compare(e.fa,n.fa))}export function ibanCodeOf(e){return e?.same_as??e?.code??null}export function keyOf(e){return e.code??e.slug}const FOLD={"ي":"ی","ى":"ی","ك":"ک","ؤ":"و","أ":"ا","إ":"ا","آ":"ا","ة":"ه"},PREFIXES=["موسسهاعتباری","بانک","bankof","bank"];export function foldForSearch(e){return toLatinDigits(e).toLowerCase().replace(/[يىكؤأإآة]/g,e=>FOLD[e]).replace(/[\s‌‍ـً-ْ'’‘\-.]/g,"")}function stripPrefix(e){const t=PREFIXES.find(t=>e.startsWith(t));return t?e.slice(t.length):e}export function searchBanks(e,t){const n=foldForSearch(t),s=stripPrefix(n);if(!s)return e.slice();const i=/^[0-9]+$/.test(n),o=[];for(const t of e){if(i){[ibanCodeOf(t),...t.alias_codes??[]].some(e=>e?.startsWith(n))&&o.push({b:t,rank:0});continue}let a=1/0;for(const i of[t.fa,t.en,...t.alias_names??[]]){const e=foldForSearch(i),o=stripPrefix(e);o.startsWith(s)?a=Math.min(a,0):(o.includes(s)||e.includes(n))&&(a=Math.min(a,1))}a!==1/0&&o.push({b:t,rank:a})}return o.sort((e,t)=>e.rank-t.rank).map(e=>e.b)}